// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue, uniqueSuffix } from '@skyramp/skyramp';
import { createCoupon, getCoupon, getCouponsList } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    const couponCode = uniqueSuffix("TESTBOT-LIFECYCLE");

    const couponsPostResponse = await createCoupon(client, headers, couponCode, 25);
    expect(couponsPostResponse.statusCode, 'status code').toBe(201);
    expect(getResponseValue(couponsPostResponse, "response.code"), 'code').toBe(couponCode);
    expect(getResponseValue(couponsPostResponse, "response.discountPercent"), 'discountPercent').toBe(25);
    expect(getResponseValue(couponsPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(couponsPostResponse, "response.createdById"), 'createdById').toBeGreaterThan(0);
    expect(getResponseValue(couponsPostResponse, "response.createdAt"), 'createdAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);
    expect(getResponseValue(couponsPostResponse, "response.updatedAt"), 'updatedAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    const createdCouponId = getResponseValue(couponsPostResponse, "response.id");
    const createdByUserId = getResponseValue(couponsPostResponse, "response.createdById");

    const couponsCouponsGetResponse = await getCoupon(client, headers, createdCouponId);
    expect(couponsCouponsGetResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(couponsCouponsGetResponse, "response.id"), 'id').toBe(createdCouponId);
    expect(getResponseValue(couponsCouponsGetResponse, "response.code"), 'code').toBe(couponCode);
    expect(getResponseValue(couponsCouponsGetResponse, "response.discountPercent"), 'discountPercent').toBe(25);
    expect(getResponseValue(couponsCouponsGetResponse, "response.createdById"), 'createdById').toBe(createdByUserId);
    expect(getResponseValue(couponsCouponsGetResponse, "response.createdAt"), 'createdAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    const couponsGetResponse = await getCouponsList(client, headers);
    expect(couponsGetResponse.statusCode, 'status code').toBe(200);
    // The list is ordered by createdAt desc and this coupon was just created, so it heads the list.
    expect(getResponseValue(couponsGetResponse, "response").length, 'owned coupon count').toBeGreaterThanOrEqual(1);
    expect(getResponseValue(couponsGetResponse, "response.0.id"), 'newest coupon id').toBe(createdCouponId);
    expect(getResponseValue(couponsGetResponse, "response.0.code"), 'newest coupon code').toBe(couponCode);
    expect(getResponseValue(couponsGetResponse, "response.0.discountPercent"), 'newest coupon discountPercent').toBe(25);
    expect(getResponseValue(couponsGetResponse, "response.0.createdById"), 'newest coupon createdById').toBe(createdByUserId);
});
